const isItem = (value) => {
    return value['id'] && value['created'] && value['data'];
};

const getSelectedTagIds = (cards, cardId) => {
  const card = cards.find((card) => isItem(card) && card.id === cardId);
  if (!card) {
    return [];
  }
  return card.data.tags.map((tag) => tag.id);
};

